mapper.sql:
WHERE o.deleted = 0

    AND o.status = #{status}


    AND o.customer_id = #{customerId}


    AND (o.title LIKE CONCAT('%', #{keyword}, '%') OR o.order_no LIKE CONCAT('%', #{keyword}, '%'))


    AND EXISTS (SELECT 1 FROM material_task t WHERE t.order_id = o.id AND t.assignee_id = #{designerId})


    AND o.deadline >= #{deadlineFrom}


    AND o.deadline <= #{deadlineTo}


    AND o.deadline < CURDATE() AND o.status IN ('PENDING_CONFIRM', 'IN_PROGRESS')


    AND o.status IN ('PENDING_CONFIRM', 'IN_PROGRESS')
    AND EXISTS (SELECT 1 FROM operation_log l
                WHERE l.order_id = o.id AND l.action = 'ORDER_DEADLINE_CHANGED')



    AND EXISTS (SELECT 1 FROM material_task t WHERE t.order_id = o.id AND t.assignee_id = #{viewerId})
